            { ""Name"": ""Admin"" },
            { ""Name"": ""Manager"" },
            { ""Name"": ""Editor"" },
            { ""Name"": ""User"" },
            { ""Name"": ""Viewer"" }
        ]";
    }
}

/// <summary>
