public class HubConnectionManager : IHubConnectionManager
{
    private readonly YourDbContext _dbContext;

    public HubConnectionManager(YourDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task AddConnectionAsync(string hubName, string connectionId)
    {
        var connection = new HubConnection { HubName = hubName, ConnectionId = connectionId };
        _dbContext.HubConnections.Add(connection);
        await _dbContext.SaveChangesAsync();
    }

    public async Task RemoveConnectionAsync(string hubName, string connectionId)
    {
        var connection = await _dbContext.HubConnections
            .FirstOrDefaultAsync(c => c.HubName == hubName && c.ConnectionId == connectionId);
        if (connection != null)
        {
            _dbContext.HubConnections.Remove(connection);
            await _dbContext.SaveChangesAsync();
        }
    }
}
