   {
       private readonly DbContext _context;

       public GenericRepository(DbContext context)
       {
           _context = context;
       }
   }
   ```
2. **Ensure `DbContext` is registered in DI** (otherwise, `GenericRepository<T>` cannot work):
   ```csharp
   builder.Services.AddDbContext<AppDbContext>(options =>
       options.UseSqlServer(Configuration.GetConnectionString("DefaultConnection")));
   ```
3. **Make sure your `GenericRepository<T>` implementation is correct and properly interfaces with `DbContext`**.

